local function UpdateUIDropdownsForWeapon(weaponName)
    if isUpdatingUI then return end
    if not (Options.SkinDropdown and Options.CharmDropdown) then return end
    isUpdatingUI = true
    local skins = skinsByWeapon[weaponName] or { weaponName }
    Options.SkinDropdown:SetValues(skins)
    local currentSkin = _G.SelectedSkins[weaponName] or weaponName
    local skinExists = false
    for _, s in ipairs(skins) do
        if s == currentSkin then
            skinExists = true
            break
        end
    end
    if not skinExists then
        currentSkin = skins[1] or weaponName
    end
    Options.SkinDropdown:SetValue(currentSkin)
    local currentCharm = _G.SelectedCharms[weaponName] or "None"
    Options.CharmDropdown:SetValue(currentCharm)
    if Options.WrapDropdown then
        local currentWrap = _G.SelectedWraps[weaponName] or "None"
        Options.WrapDropdown:SetValue(currentWrap)
    end
    isUpdatingUI = false
end
